function hmd_detail_link(array $d):array{$urls=[];$walk=function(mixed $v,string $key='',int $depth=0)use(&$walk,&$urls):void{if($depth>7)return;if(is_array($v)){foreach($v as$k=>$x)$walk($x,(string)$k,$depth+1);return;}if(!is_string($v)||!preg_match('/(?:url|link)/i',$key))return;$u=trim($v);if($u===''||strlen($u)>2048)return;$p=parse_url($u);if(!is_array($p)||!in_array(strtolower((string)($p['scheme']??'')),['http','https'],true)||empty($p['host']))return;$urls[$u]=true;};$walk($d);$native=[];foreach(array_keys($urls)as$u){$p=parse_url($u);parse_str((string)($p['query']??''),$q);foreach($q as$k=>$v){if(!in_array(strtolower((string)$k),['hotellist','hotelcode','hotel_code','hotelid','hotel_id','hotelinc','hotel'],true))continue;foreach((array)$v as$item)foreach(preg_split('/[,;]+/',(string)$item)?:[]as$x)if(preg_match('/^[1-9][0-9]{0,12}$/D',trim($x)))$native[(int)trim($x)]=true;}}$ids=array_keys($native);sort($ids,SORT_NUMERIC);return['urls'=>array_slice(array_keys($urls),0,12),'native_ids'=>$ids];}
function hmd_tv_search_id(array $p):?int{foreach(['searchId','id']as$k){$n=hmd_id($p[$k]??null);if($n)return$n;}foreach($p as$v)if(is_array($v)){if($n=hmd_tv_search_id($v))return$n;}return null;}
function hmd_tv_complete(array $p):bool{if((int)($p['progress']??0)>=100)return true;if(in_array(hmd_norm(hmd_text($p['status']??'')),['complete','completed','done','ready'],true))return true;foreach($p as$v)if(is_array($v)&&hmd_tv_complete($v))return true;return false;}
